import{_ as d,o as a,c as l,a4 as r}from"./chunks/framework.BYKJayo6.js";const c=JSON.parse('{"title":"DLC03・デルタの夜明け","description":"Anno 117 DLC03「デルタの夜明け（Dawn of the Delta）」の情報ページ。エジプト地方アイギュプト・灌漑システム・新祭神セベクなどを解説（2026年11月5日リリース）。","frontmatter":{"title":"DLC03・デルタの夜明け","description":"Anno 117 DLC03「デルタの夜明け（Dawn of the Delta）」の情報ページ。エジプト地方アイギュプト・灌漑システム・新祭神セベクなどを解説（2026年11月5日リリース）。"},"headers":[],"relativePath":"guide/dlc03-dawn-of-delta.md","filePath":"guide/dlc03-dawn-of-delta.md"}'),i={name:"guide/dlc03-dawn-of-delta.md"};function e(o,t,n,h,s,u){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="dlc03・デルタの夜明け" tabindex="-1">DLC03・デルタの夜明け <a class="header-anchor" href="#dlc03・デルタの夜明け" aria-label="Permalink to &quot;DLC03・デルタの夜明け&quot;">​</a></h1><blockquote><p>本ページの内容は今後変更される可能性があります。</p></blockquote><blockquote><p>このページは作成中です。確定情報が増え次第、随時更新します。</p></blockquote><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><ul><li>舞台は帝国南東部の<strong>アイギュプト</strong>（ナイル川デルタ地方）。</li><li>新規ゲーム開始時の地域として選択できるほか、既存セーブでもDLC有効化により探索可能になります。</li><li><strong>灌漑システム</strong>・新祭神・独自の軍事ユニットが導入されます。</li><li><strong>2026年11月5日</strong>、無料アップデート3.0と同時にリリースされました。</li></ul><h2 id="地形・建築エリア" tabindex="-1">地形・建築エリア <a class="header-anchor" href="#地形・建築エリア" aria-label="Permalink to &quot;地形・建築エリア&quot;">​</a></h2><p>土地は3つのゾーンに分かれます。</p><table tabindex="0"><thead><tr><th>ゾーン</th><th>特徴</th></tr></thead><tbody><tr><td>砂漠エリア</td><td>内陸にあり、作物は作れないが、建物は建てられる。都市の建設に適している</td></tr><tr><td>農地</td><td>海岸沿いにあり、農業と港の建設に使う</td></tr><tr><td>氾濫原</td><td>川沿いにあり、洪水の影響を受ける。泥のおかげで建物の生産量が増える。葦・泥などの産地</td></tr></tbody></table><p>「農地」と「氾濫原」は、農場の建設画面に出る「地形のタイプ」の表記で、実機で確認しました。オーツ麦農場のように、農地と氾濫原のどちらにも建てられる農場があります。氾濫原に建てると、「1tをサイクル毎に追加で生産」の効果が付きます。「砂漠エリア」はゲーム内の表記ではなく、このWikiでの呼び名です（日本語版の正式な表記は未確認です）。実機で、作物は作れず、建物は建てられることを確認しました。</p><h2 id="住民層" tabindex="-1">住民層 <a class="header-anchor" href="#住民層" aria-label="Permalink to &quot;住民層&quot;">​</a></h2><p>初期層は<strong>麦打ち人</strong>（農業の伝統を担う階層）です。基本の需要を満たすと、次の2路線から選びます。</p><table tabindex="0"><thead><tr><th>路線</th><th>第2階層</th><th>第3階層</th></tr></thead><tbody><tr><td>クマト（伝統）</td><td>陶工</td><td>奉唱巫女</td></tr><tr><td>ギリシャ・ローマ</td><td>書記</td><td>ギムナシアリコス</td></tr></tbody></table><p>各層の需要は<a href="/wiki/population.html#アイギュプト住民層">住民層のページ</a>にまとめています。</p><h2 id="公共施設" tabindex="-1">公共施設 <a class="header-anchor" href="#公共施設" aria-label="Permalink to &quot;公共施設&quot;">​</a></h2><ul><li><strong>クマト路線</strong>: 薬局（薬草園つき。健康と知識）、聖域または神殿（現地の神々）、岩窟墓（上流階級向け。山のスロットが必要）、天文台（信仰+5、知識+3）。</li><li><strong>ローマ路線</strong>: 劇場、浴場（水道橋が必要）、図書館（オイルランプに注意）。</li></ul><h2 id="新しい商品・生産チェーン" tabindex="-1">新しい商品・生産チェーン <a class="header-anchor" href="#新しい商品・生産チェーン" aria-label="Permalink to &quot;新しい商品・生産チェーン&quot;">​</a></h2><ul><li><strong>魔除けのお守り</strong>（陶工向け）: 銅と砂から青い染料を作り、現地の粘土で作った魔除けのお守りを染めます。</li><li><strong>書記道具一式</strong>（書記向け）: パピルス（葦が必要）と、現地の鉱物から作る顔料で作ります。</li><li><strong>シストラム</strong>（奉唱巫女向け）: 現地の銅と錫から作った青銅に、氾濫原で採れるビーズを組み合わせます。</li><li>パン・ビール・石鹸などは、ラティウム・アルビオン・アイギュプトのどこで作るか、輸入か現地生産かを選べます。</li><li>需要品の一覧は<a href="/wiki/population.html#アイギュプト住民層">住民層のページ</a>を参照。</li><li><strong>ラティウムの住民も、アイギュプトの商品を欲しがります</strong>。アップデート3.0で、エクィテスの需要にナツメヤシ・コール・書記道具一式が、パトリキの需要にそれらとカフク・ポッパエアのミルク・象牙の小箱・シストラムが加わりました（実機で確認）。ラティウムの島の需要を満たすには、アイギュプトからの輸入が必要です。詳しくは<a href="/wiki/population.html#エクィテス">住民層のページ</a>を参照。アルビオンも同じで、ケルト文化路線のスミスにコール・魔除けのお守りが、アルダーにそれらと青スイレン茶が、ローマ文化路線のメルカトルに書記道具一式が、ノビレスにそれと希少な肉の盛り合わせ・香油が加わりました（アルダーの青スイレン茶と魔除けのお守りは実機で確認。ほかはゲーム内データで、実機では未確認です）。</li></ul><h2 id="アイギュプトの生産施設" tabindex="-1">アイギュプトの生産施設 <a class="header-anchor" href="#アイギュプトの生産施設" aria-label="Permalink to &quot;アイギュプトの生産施設&quot;">​</a></h2><p>アイギュプトで新しく作れる商品の生産施設です。サイクルは1サイクルの秒数で、労働力はその施設に必要な住民層と人数です。維持費の単位はコインです。</p><table tabindex="0"><thead><tr><th>施設</th><th>サイクル（秒）</th><th>労働力</th><th>維持費</th><th>材料</th><th>製品</th></tr></thead><tbody><tr><td>青色顔料工房</td><td>90</td><td>陶工8</td><td>20</td><td>銅鉱石、シリカ</td><td>アイギュプトの青</td></tr><tr><td>ゴマ圧搾所</td><td>90</td><td>陶工8</td><td>16</td><td>ゴマのさや</td><td>ゴマ油</td></tr><tr><td>詰め物肉工房</td><td>120</td><td>陶工6</td><td>14</td><td>雁、小麦</td><td>詰め物入りガチョウ</td></tr><tr><td>カイク工房</td><td>90</td><td>奉唱巫女12</td><td>22</td><td>蜂の巣、小麦粉</td><td>カフク</td></tr><tr><td>煎じ茶工房</td><td>90</td><td>奉唱巫女12</td><td>22</td><td>青スイレン、蜂の巣</td><td>青スイレン茶</td></tr><tr><td>ビーズ工房</td><td>90</td><td>麦打ち人4</td><td>8</td><td>ビーズ</td><td>ウェセクの首輪</td></tr><tr><td>プリーツ工房</td><td>90</td><td>陶工6</td><td>10</td><td>布</td><td>シェンティ</td></tr><tr><td>コリュラ工房</td><td>90</td><td>陶工6</td><td>10</td><td>獣脂、石炭</td><td>コール</td></tr><tr><td>裁縫工房</td><td>90</td><td>奉唱巫女10</td><td>24</td><td>布、アイギュプトの青</td><td>カラシリス</td></tr><tr><td>香油工房</td><td>90</td><td>奉唱巫女8</td><td>14</td><td>青スイレン、ゴマ油</td><td>香油</td></tr><tr><td>ガラス細工工房</td><td>90</td><td>陶工6</td><td>12</td><td>泥、アイギュプトの青</td><td>魔除けのお守り</td></tr><tr><td>ランプ工房</td><td>90</td><td>陶工8</td><td>14</td><td>泥、ゴマ油</td><td>オイルランプ</td></tr><tr><td>ティンパニ工房</td><td>120</td><td>奉唱巫女12</td><td>24</td><td>ビーズ、青銅</td><td>シストラム</td></tr><tr><td>泥レンガ集積場</td><td>30</td><td>麦打ち人2</td><td>8</td><td>泥、葦</td><td>泥レンガ</td></tr><tr><td>石灰岩の石工所</td><td>60</td><td>陶工5</td><td>10</td><td>石灰岩</td><td>石灰岩レンガ</td></tr><tr><td>メリクラトール</td><td>90</td><td>ギムナシアリコス8</td><td>12</td><td>蜂の巣、サンガ牛</td><td>蜂蜜入りミルク</td></tr><tr><td>パピルス職人</td><td>120</td><td>書記6</td><td>12</td><td>葦</td><td>パピルス</td></tr><tr><td>大地の美食家</td><td>120</td><td>ギムナシアリコス8</td><td>16</td><td>カバ、ザクロ</td><td>希少な肉の盛り合わせ</td></tr><tr><td>美容師</td><td>120</td><td>ギムナシアリコス8</td><td>16</td><td>ザクロ、蜂蜜入りミルク</td><td>ポッパエアのミルク</td></tr><tr><td>写本室</td><td>120</td><td>書記4</td><td>14</td><td>顔料、パピルス</td><td>書記道具一式</td></tr><tr><td>錠前師</td><td>90</td><td>ギムナシアリコス12</td><td>30</td><td>金、カバ</td><td>象牙の小箱</td></tr><tr><td>ナツメヤシ農場</td><td>60</td><td>麦打ち人4</td><td>6</td><td>—</td><td>ナツメヤシ</td></tr><tr><td>ラクダ牧場</td><td>120</td><td>陶工6</td><td>12</td><td>—</td><td>ラクダ</td></tr><tr><td>青スイレン農園</td><td>120</td><td>奉唱巫女8</td><td>4</td><td>—</td><td>青スイレン</td></tr><tr><td>ザクロ農場</td><td>90</td><td>麦打ち人4</td><td>8</td><td>—</td><td>ザクロ</td></tr><tr><td>サンガ牛牧場</td><td>60</td><td>麦打ち人4</td><td>8</td><td>—</td><td>サンガ牛</td></tr><tr><td>ビーズ工房</td><td>90</td><td>麦打ち人4</td><td>4</td><td>—</td><td>ビーズ</td></tr><tr><td>雁狩り小屋</td><td>60</td><td>麦打ち人6</td><td>6</td><td>—</td><td>雁</td></tr><tr><td>大型獣の狩猟小屋</td><td>60</td><td>ギムナシアリコス6</td><td>12</td><td>—</td><td>カバ</td></tr><tr><td>ゴマ農場</td><td>120</td><td>麦打ち人4</td><td>4</td><td>—</td><td>ゴマのさや</td></tr></tbody></table><ul><li>数値はゲームのアップデート3.0のゲーム内データです。実機の画面との照合は未確認です。</li><li>「ビーズ工房」は2種類あります。ビーズを作る施設と、ビーズからウェセクの首輪を作る施設です。</li><li>労働力の表記は「住民層＋人数」です。たとえば「陶工8」は、陶工の労働力が8必要という意味です。</li></ul><h2 id="穀倉" tabindex="-1">穀倉 <a class="header-anchor" href="#穀倉" aria-label="Permalink to &quot;穀倉&quot;">​</a></h2><ul><li>範囲内の農場の生産性が+15%、人口ボーナスが+1。農産物を1基あたり100t追加で保管できます。</li><li>スキルでアップグレードできます。</li><li>保管上限を超えるとあふれ、ネズミが出ることがあります。超過が多く、穀倉のレベルが低いほど起きやすく、島の健康度が下がって総督の決定を誘発します。</li><li>対策は、穀倉のアップグレードと、ネズミ対策の専門家の雇用です。 <ul><li><strong>猫の友キャットゥルス</strong>（レア）: ネズミの危険性が60%下がります。多数の交易商や祭りから、低確率でランダムに手に入ります。</li><li><strong>猫使い</strong>（コモン）: ネズミの危険性が20%下がります。ヘロン地方長官やウァレリアなどとの取引で手に入ります。</li><li><strong>ミウト、水鳥の脅威</strong>（レジェンダリー、財政）: 総督のヴィラに付けると、信仰の範囲効果が+2になり、ネズミの危険性も抑えます。ネズミの危険性は80%下がるとデータにあり、入手先はクエスト「パンドラのアンフォラ」です（この2点は実機では未確認です）。</li></ul></li></ul><h2 id="洪水と灌漑" tabindex="-1">洪水と灌漑 <a class="header-anchor" href="#洪水と灌漑" aria-label="Permalink to &quot;洪水と灌漑&quot;">​</a></h2><h3 id="季節の影響" tabindex="-1">季節の影響 <a class="header-anchor" href="#季節の影響" aria-label="Permalink to &quot;季節の影響&quot;">​</a></h3><ul><li><strong>氾濫期</strong>: 氾濫原の建物の生産性が75%下がります。州全体で、全建物の健康が-2、防火が+2になります。</li><li><strong>収穫期</strong>: 氾濫原の生産建物の生産量が、サイクルごとに+1tになります。</li></ul><h3 id="灌漑の方式" tabindex="-1">灌漑の方式 <a class="header-anchor" href="#灌漑の方式" aria-label="Permalink to &quot;灌漑の方式&quot;">​</a></h3><ul><li><strong>ベイスン方式</strong>: 海岸に貯水池（ベイスン）を建て、内陸へ運河を伸ばします。運河の両側8フィールドが農地になり、乾燥地帯を農業用地に変えられます。その分、都市の建設スペースは減ります。農業専用の島を作る手もあります。</li><li><strong>水路の水溜め</strong>: 運河に接続し、道路もつなぐと、範囲内で健康+1、防火+3になります。</li><li><strong>ノリア方式</strong>（第3階層で解放）: 川の水をノーリア水車でくみ上げ、水道橋で内陸へ送ります。貯水槽（シスターン）は浴場の水源になるほか、周囲の円形範囲も農地にします。</li></ul><h2 id="スキルツリー" tabindex="-1">スキルツリー <a class="header-anchor" href="#スキルツリー" aria-label="Permalink to &quot;スキルツリー&quot;">​</a></h2><p>アイギュプトには、専用のスキルツリーが用意されます。スキルで次のことができるようになります。</p><ul><li>氾濫原でより多様な作物を育て、生産ボーナスを得る。</li><li>灌漑設備を強化して、生産建物の水使用量を減らす。長い運河も建設できるようになる。</li><li>アイギュプトで石鹸などを生産できるようにする。</li><li>現地の新しい神々を発見する。</li></ul><h2 id="宗教" tabindex="-1">宗教 <a class="header-anchor" href="#宗教" aria-label="Permalink to &quot;宗教&quot;">​</a></h2><p>新祭神が3柱導入されます。名前はゲームのアップデート3.0のゲーム内データの表記です。</p><ul><li><strong>セベク</strong>：「デルタ川の神」。研究なしで使えます。チーズソーセージ・詰めガチョウ・サンガ牛などの食料生産が増え、灌漑用水とボーナス人口も増えます。世界的な信仰ボーナスで鳩小屋が解放され、農園に付けると生産性が上がります。鳩小屋は農園に取り付けるモジュールで、サイロと同じ仕組みです。小麦を消費して動き、生産性と処理時間があります（実機で確認）。なお、ゲーム内ヘルプによると、サイロが機能するには範囲内に倉庫が必要です。</li><li><strong>イシス・バステト</strong>：研究ツリーで発見が必要です。ラベンダー・香水・ナツメヤシの生産が増え、住民の商品消費量は減ります。世界の信仰が4,000になると、特大の祭壇「レプリカのスフィンクスの祭壇」が解放されます（実機で確認。範囲効果は人々+1・収入+1・名声+2、維持費26、島の上限10）。世界の信仰がさらに高いと、祭りの期間が延びます。</li><li><strong>トト・トリスメギストス</strong>：研究ツリーで発見が必要です。ガラス・ワイン・書字板・書記道具一式などの生産が増えます。島の収入と名声は知識レベルに連動します。世界の信仰が高まると、崇拝の効果「トトの書」で、図書館の範囲内の全建物の生産が20%増えます（実機で確認）。</li></ul><p>エジプトの神を信仰すると、聖域・神殿の外観がエジプト風（猫やワニの聖域など）になります。</p><h2 id="ピラミッド" tabindex="-1">ピラミッド <a class="header-anchor" href="#ピラミッド" aria-label="Permalink to &quot;ピラミッド&quot;">​</a></h2><p>島ではなく、州全体のプロジェクトです。ナウクラティスの近くにあり、修復すると州全体にボーナスが付きます。</p><ul><li>修復の各段階で、タイル・花崗岩・大理石・チュニック・労働者の食料・輸送用のヒトコブラクダなどを、ピラミッド用の波止場に納めます。</li><li>段階ごとの効果は、全島での帝国の土地税の低下と名声の上昇です。ライバルがいると、先に必要量を納めた総督ほど強い効果を得られます。</li><li>完成時にピリミディオン（頂石）を載せると、州全体の名声ボーナスと、英雄スペシャリストの出現確率の一時的な上昇が得られます。新しい英雄スペシャリストは3人です。</li><li>儀式を定期的に行うと、効果の持続時間を延ばせます。</li><li>修復したピラミッドは、第3階層（奉唱巫女・ギムナシアリコス）の需要になり、幸福と名声を与えます。</li></ul><h2 id="キャラクター" tabindex="-1">キャラクター <a class="header-anchor" href="#キャラクター" aria-label="Permalink to &quot;キャラクター&quot;">​</a></h2><p>メインストーリーは殺人ミステリーで、ナウクラティスで遺体が見つかるところから始まります。ストーリーを飛ばして、島の経営に専念することもできます。</p><table tabindex="0"><thead><tr><th>名前</th><th>役割</th></tr></thead><tbody><tr><td>エピストラテゴス・ヘロン（Epistrategos Heron）</td><td>ナウクラティスの皇帝代理人。軍事力はほぼ無く、仲介役・商人</td></tr><tr><td>ヴァレリア（Valeria）</td><td>川沿いの小さな港を拠点に、交易帝国を広げる</td></tr><tr><td>カンディス（Kandis）</td><td>ファラオの谷を拠点とする略奪者。身代金を要求し、払わないと攻撃してくる。倒すには、港の破壊と谷への軍の派遣が必要</td></tr><tr><td>デキムス・ナウクラティウス・ネルウァ（Decimus Naukratius Nerva）</td><td>「エジプトの暴君」。ライバル総督として追加できる。キャンペーン主人公の父</td></tr></tbody></table><p>日本語名は仮の訳です。</p><h2 id="新軍事ユニット・船舶" tabindex="-1">新軍事ユニット・船舶 <a class="header-anchor" href="#新軍事ユニット・船舶" aria-label="Permalink to &quot;新軍事ユニット・船舶&quot;">​</a></h2><ul><li><strong>エリート・クシテ弓兵</strong>（Kumatic Archers）：通常の遠距離ユニットより攻撃力・命中率・射程が高い。採用費と維持費も高い。</li><li><strong>ドロメダリイ騎兵</strong>（ラクダ騎兵）：敵の騎兵・歩兵ユニットの士気を低下させる効果を持ちます。騎馬ユニットに強くやや安価ですが、足の速い馬には追いつけません。</li><li>2体とも、スキルツリーで先に研究する必要があります。スキルの1つで、ラティウム以外でもレギオナリウス（軍団兵）を徴募できるようになります。</li><li>アイギュプト専用の造船所で、改造できない船を2種建造できます。 <ul><li>スキフ（Skiff、エポルコン）：最初から建造可能。非武装で、貨物スロットは3。</li><li>ガレー（Galley、アバ）：スキルで解放。貨物スロットは5。軍事型は複数のアーチャーを載せられます。</li></ul></li><li>ローマ船は外洋向けで頑丈ですが、浅い河口のデルタでは扱いにくく、アイギュプト船は浅瀬に強く速いです。川の輸送は現地の船、地域間の輸送はローマ船に積み替える使い分けが勧められています。海岸近くの貨物ハブも有用とされています。</li></ul><h2 id="その他" tabindex="-1">その他 <a class="header-anchor" href="#その他" aria-label="Permalink to &quot;その他&quot;">​</a></h2><ul><li>他地域との交易により、独自の経済戦略を構築できます。</li></ul><h2 id="無料アップデート3-0の内容" tabindex="-1">無料アップデート3.0の内容 <a class="header-anchor" href="#無料アップデート3-0の内容" aria-label="Permalink to &quot;無料アップデート3.0の内容&quot;">​</a></h2><p>DLC03と同じ<strong>2026年11月5日</strong>（日本時間19:00）に配信されました。</p><h3 id="新機能" tabindex="-1">新機能 <a class="header-anchor" href="#新機能" aria-label="Permalink to &quot;新機能&quot;">​</a></h3><ul><li><strong>スタンプ機能</strong>：住居や生産施設の配置を保存して、あとで再利用できます。フォルダに分けて整理もできます</li><li>統計メニューに「保管」タブと「アイテム・スペシャリスト」タブを追加 <ul><li>保管タブでは、保管中の商品、パッシブ貿易、アクティブ貿易、保管量の増減を確認できます</li><li>アイテム・スペシャリストタブでは、持っているスペシャリストと、まだ手に入れていないスペシャリスト、その入手元を一覧できます</li></ul></li><li>クエストログからクエストを隠せるようになります。隠したクエストは、クエストブックから戻せます</li><li>祭りを自動で承認するオプションを追加</li></ul><h3 id="バランス調整" tabindex="-1">バランス調整 <a class="header-anchor" href="#バランス調整" aria-label="Permalink to &quot;バランス調整&quot;">​</a></h3><ul><li>新しいセーブでは、難易度「ノーマル」が既定になり、商品の消費量が増えます。「簡単」も選べます。消費がさらに75%増える最上位の難易度も追加されます</li><li>開始資金が増えます</li><li>祭りを始めるのに必要な商品が、商品の価値で決まるようになります。安い商品は多く、高い商品は少なく必要です。終盤の祭りの費用は、50,000コインから25,000コインに下がります</li><li>都市ステータスの属性ペナルティの増え方が、人口ティア2・3の前後でゆるやかになります</li></ul><h3 id="栄誉の殿堂" tabindex="-1">栄誉の殿堂 <a class="header-anchor" href="#栄誉の殿堂" aria-label="Permalink to &quot;栄誉の殿堂&quot;">​</a></h3><ul><li>新カテゴリ「Aegyptus」が加わります。DLC03を持っていなくても使えます</li></ul><h3 id="ps5・xbox" tabindex="-1">PS5・Xbox <a class="header-anchor" href="#ps5・xbox" aria-label="Permalink to &quot;PS5・Xbox&quot;">​</a></h3><ul><li>インストールサイズが小さくなります。そのぶん、今回の更新のダウンロードは大きくなります</li></ul><p>詳しいパッチノートは、2026年11月2日に<a href="https://www.anno-union.com/updates/anno-117-pax-romana-patch-3-0/" target="_blank" rel="noreferrer">公式サイト（Anno Union）</a>で公開されています。</p><h2 id="まだ分かっていない要素" tabindex="-1">まだ分かっていない要素 <a class="header-anchor" href="#まだ分かっていない要素" aria-label="Permalink to &quot;まだ分かっていない要素&quot;">​</a></h2><p>以下は、まだ分かっていません。</p><ul><li>ピラミッドの各段階の必要量と効果量、儀式の内容</li><li>数値バランス（生産量・信仰要求量など）の、実機での確認</li></ul><p>建物・生産施設・需要品・スキルツリーなどの数値は、配信前のゲーム内データ（アップデート3.0）から載せています。実機との照合は未確認なので、配信後に確かめて直します。</p><h2 id="関連データ" tabindex="-1">関連データ <a class="header-anchor" href="#関連データ" aria-label="Permalink to &quot;関連データ&quot;">​</a></h2><ul><li><a href="/wiki/">データベース一覧</a> — 現在公開中のゲームデータ</li></ul>',63)])])}const p=d(i,[["render",e]]);export{c as __pageData,p as default};
